package com.vibeguard.samples.reset; import jakarta.validation.Valid; import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Issues and verifies one-time, hashed password reset tokens. */ @RestController @RequestMapping("/api/password-resets") public class PasswordResetController { private final Map<String,Reset> resets=new ConcurrentHashMap<>(); private final SecureRandom random=new SecureRandom(); @PostMapping public ResponseEntity<Void> request(@Valid @RequestBody Request request)throws Exception{byte[] bytes=new byte[32];random.nextBytes(bytes);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);resets.put(hash(token),new Reset(request.email(),Instant.now().plus(Duration.ofMinutes(15))));return ResponseEntity.accepted().build();}@PostMapping("/confirm") public ResponseEntity<Void> confirm(@Valid @RequestBody Confirm confirm)throws Exception{Reset reset=resets.remove(hash(confirm.token()));if(reset==null||Instant.now().isAfter(reset.expiresAt()))return ResponseEntity.status(400).build();return ResponseEntity.noContent().build();}private String hash(String token)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}record Request(@Email String email){}record Confirm(@NotBlank String token,@NotBlank String newPassword){}record Reset(String email,Instant expiresAt){} }
